pub fn vstack(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    // Problem states equal length; keep a debug check to catch misuse during development.
    debug_assert_eq!(a.len(), b.len());

    let mut result = Vec::with_capacity(2);
    result.push(a);
    result.push(b);
    result
}

/// Creates the outer product matrix of vectors `a` and `b`.
/// The result has `a.len()` rows and `b.len()` columns:
/// result[i][j] = a[i] * b[j]
pub fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    let m = a.len();
    let n = b.len();

    let mut result: Vec<Vec<f32>> = Vec::with_capacity(m);
    for &ai in a.iter() {
        let mut row = Vec::with_capacity(n);
        for &bj in b.iter() {
            row.push(ai * bj);
        }
        result.push(row);
    }
    result
}

